    for (config_override, ignored_path) in [
        ("foo=bar", "foo"),
        ("tui.bogus_key_xyz=1", "tui.bogus_key_xyz"),
    ] {
        let codex_home = TempDir::new()?;
        let mut cmd = codex_command(codex_home.path())?;
        cmd.args(["--strict-config", "-c", config_override, "exec", "hello"])
            .assert()
