    assert!(
        output.status.success()
            && String::from_utf8_lossy(&output.stdout).contains(CHILD_COMPLETED),
        "filesystem spawn test failed:\n{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr),
    );
    Ok(())
}

