            assert_eq!(message["id"], "legacy-approval");
            assert_eq!(message["result"]["action"], "accept");
            assert_eq!(message["result"]["content"], legacy_schema_defaults());
            write_message(
                &mut stdout,
                json!({
                    "jsonrpc": "2.0",
                    "id": pending_call,
                    "result": {"content": [{"type": "text", "text": "legacy approved"}]},
                }),
            )?;
            continue;
        };

        match method {
            "server/discover" if is_legacy => {
                assert_eq!(mode, "legacy-fallback");
                write_message(
                    &mut stdout,
                    json!({
                        "jsonrpc": "2.0",
                        "id": message["id"],
                        "error": {"code": -32601, "message": "method not found"},
                    }),
                )?;
            }
            "server/discover" => {
                assert!(!initialized);
                assert_modern_metadata(&message);
                initialized = true;
                write_message(
                    &mut stdout,
                    json!({
                        "jsonrpc": "2.0",
                        "id": message["id"],
                        "result": {
                            "resultType": "complete",
                            "supportedVersions": [MODERN_VERSION],
                            "capabilities": {"tools": {}, "resources": {}},
                            "_meta": {
                                "io.modelcontextprotocol/serverInfo": {
                                    "name": "strict-stdio-test",
                                    "version": "1.0.0",
                                },
                            },
                            "ttlMs": 0,
                            "cacheScope": "private",
                        },
                    }),
                )?;
            }
            "initialize" => {
                assert!(is_legacy);
                assert_eq!(message["params"]["protocolVersion"], LEGACY_VERSION);
                initialized = true;
                write_message(
                    &mut stdout,
                    json!({
                        "jsonrpc": "2.0",
                        "id": message["id"],
                        "result": {
                            "protocolVersion": LEGACY_VERSION,
                            "capabilities": {"tools": {}},
                            "serverInfo": {"name": "legacy-stdio-test", "version": "1.0.0"},
                        },
                    }),
                )?;
            }
            "notifications/initialized" => assert!(is_legacy),
            "tools/list" => {
                assert!(initialized);
                if !is_legacy {
                    assert_modern_metadata(&message);
                }
                let description = if oversized {
                    "x".repeat(MAX_MESSAGE_BYTES + 1)
                } else {
                    "echo a value".to_owned()
                };
                let mut result = json!({
                    "tools": [{
                        "name": "echo",
                        "description": description,
                        "inputSchema": {"type": "object"},
                    }],
                });
                if !is_legacy {
                    result["resultType"] = json!("complete");
                    result["ttlMs"] = json!(0);
                    result["cacheScope"] = json!("private");
                }
                write_message(
                    &mut stdout,
                    json!({"jsonrpc": "2.0", "id": message["id"], "result": result}),
                )?;
            }
            "tools/call" if is_legacy => {
                assert!(initialized);
                pending_legacy_call = Some(message["id"].clone());
                write_message(
                    &mut stdout,
                    json!({
                        "jsonrpc": "2.0",
                        "id": "legacy-approval",
                        "method": "elicitation/create",
                        "params": {
                            "message": "Accept the schema defaults",
                            "requestedSchema": {
                                "type": "object",
                                "properties": {
                                    "name": {"type": "string", "default": "John Doe"},
                                    "age": {"type": "integer", "default": 30},
                                    "score": {"type": "number", "default": 95.5},
                                    "status": {
                                        "type": "string",
                                        "enum": ["active", "inactive"],
                                        "default": "active",
                                    },
                                    "verified": {"type": "boolean", "default": true},
                                },
                                "required": [],
                            },
                        },
                    }),
                )?;
            }
            "tools/call" => {
                assert!(initialized);
                assert_modern_metadata(&message);
                if message.pointer("/params/inputResponses").is_none() {
                    write_message(
                        &mut stdout,
                        json!({
                            "jsonrpc": "2.0",
                            "id": message["id"],
                            "result": {
                                "resultType": "input_required",
                                "inputRequests": {
                                    "approval": {
                                        "method": "elicitation/create",
                                        "params": {
                                            "mode": "form",
                                            "message": "Approve stdio call?",
                                            "requestedSchema": {
                                                "type": "object",
                                                "properties": {
                                                    "approved": {"type": "boolean"},
                                                },
                                            },
                                        },
                                    },
                                },
                                "requestState": "stdio-state",
                                "_meta": {
                                    "io.modelcontextprotocol/serverInfo": {
                                        "name": "strict-stdio-test",
                                        "version": "1.0.0",
                                    },
                                },
                            },
                        }),
                    )?;
                    continue;
                }

                assert_eq!(message["params"]["requestState"], "stdio-state");
                assert_eq!(
                    message["params"]["inputResponses"]["approval"]["action"],
                    "accept"
                );
                assert_eq!(
                    message["params"]["inputResponses"]["approval"]["content"]["approved"],
                    true
                );
                write_message(
                    &mut stdout,
                    json!({
                        "jsonrpc": "2.0",
                        "id": message["id"],
                        "result": {
                            "resultType": "complete",
                            "content": [{"type": "text", "text": "modern approved"}],
                        },
                    }),
                )?;
            }
            other => anyhow::bail!("unexpected MCP method {other}"),
        }
    }

    Ok(())
}

