where
    P: AsRef<Path> + Clone + Eq + Hash,
{
    for path in &mut paths {
        if path.as_ref() == old_path {
            *path = new_path.clone();
        }
    }
    let mut seen = HashSet::new();
    paths.retain(|path| seen.insert(path.clone()));
    paths
}

