//! Exercise the real helper protocol and bounded process I/O.

use std::process::Stdio;
use std::time::Duration;

use anyhow::Context;
use anyhow::Result;
use codex_realtime_webrtc::Message;
use codex_realtime_webrtc::decode_frame;
use codex_realtime_webrtc::encode_frame;
use codex_utils_cargo_bin::cargo_bin;
use pretty_assertions::assert_eq;
use tokio::io::AsyncReadExt;
use tokio::io::AsyncWriteExt;
use tokio::process::Child;
use tokio::process::Command;
use tokio::time::timeout;

const DEADLINE: Duration = Duration::from_secs(/*secs*/ 10);

fn spawn() -> Result<Child> {
    Ok(Command::new(cargo_bin("codex-voice-host")?)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true)
        .spawn()?)
}

async fn build_commit() -> Result<String> {
    let output = timeout(
        DEADLINE,
        Command::new(cargo_bin("codex-voice-host")?)
            .arg("--build-commit")
            .kill_on_drop(true)
            .output(),
    )
    .await??;
    assert!(output.status.success());
    Ok(String::from_utf8(output.stdout)?.trim().to_owned())
}

async fn handshake(child: &mut Child) -> Result<()> {
    child
        .stdin
        .as_mut()
        .context("stdin")?
        .write_all(&encode_frame(&Message::Hello {
            protocol: 1,
            build_commit: build_commit().await?,
        })?)
        .await?;
    let expected = encode_frame(&Message::Ready {})?;
    let mut reply = vec![0; expected.len()];
    timeout(
        DEADLINE,
        child
            .stdout
            .as_mut()
            .context("stdout")?
            .read_exact(&mut reply),
    )
    .await??;
    assert_eq!(reply, expected);
    Ok(())
}

#[tokio::test]
async fn closes_after_acknowledgement_and_on_parent_pipe_loss() -> Result<()> {
    for explicit_close in [true, false] {
        let mut child = spawn()?;
        handshake(&mut child).await?;
        if explicit_close {
            child
                .stdin
                .as_mut()
                .unwrap()
                .write_all(&encode_frame(&Message::Close {})?)
                .await?;
        }
        drop(child.stdin.take());
        let output = timeout(DEADLINE, child.wait_with_output()).await??;
        assert!(output.status.success());
        assert_eq!(
            output.stdout,
            if explicit_close {
                encode_frame(&Message::Closed {})?
            } else {
                vec![]
            }
        );
        assert!(output.stderr.is_empty());
    }
    Ok(())
}

#[tokio::test]
async fn parent_pipe_loss_cancels_transport_startup() -> Result<()> {
    let mut child = spawn()?;
    handshake(&mut child).await?;
    child
        .stdin
        .take()
        .unwrap()
        .write_all(&encode_frame(&Message::StartTransport {})?)
        .await?;
    let output = timeout(Duration::from_secs(/*secs*/ 5), child.wait_with_output()).await??;
    assert!(output.stderr.is_empty());
    Ok(())
}

#[tokio::test]
async fn rejects_invalid_input_without_echoing_it() -> Result<()> {
    assert!(decode_frame(b"\0\0\0\x16{\"type\":\"close\",\"x\":0}").is_err());
    let mut invalid_json = 22_u32.to_be_bytes().to_vec();
    invalid_json.extend_from_slice(b"sensitive-invalid-json");
    for frame in [
        u32::MAX.to_be_bytes().to_vec(),
        vec![0, 0],
        invalid_json,
        encode_frame(&Message::Hello {
            protocol: 1,
            build_commit: "wrong-build".into(),
        })?,
        encode_frame(&Message::Hello {
            protocol: 99,
            build_commit: build_commit().await?,
        })?,
        encode_frame(&Message::Close {})?,
    ] {
        let mut child = spawn()?;
        child.stdin.take().unwrap().write_all(&frame).await?;
        let output = timeout(DEADLINE, child.wait_with_output()).await??;
        assert!(!output.status.success());
        assert_eq!((output.stdout, output.stderr), (vec![], vec![]));
    }
    Ok(())
}

//! Exercise native initialization with real prepared libraries in a relocated package.

use std::fs;
use std::time::Duration;

use anyhow::Context;
use anyhow::Result;
use anyhow::ensure;
use codex_install_context::InstallContext;
use codex_realtime_webrtc::VoiceHost;
use codex_utils_cargo_bin::cargo_bin;
use tokio::process::Command;
use tokio::time::timeout;

const DEADLINE: Duration = Duration::from_secs(/*secs*/ 10);

#[tokio::test]
#[ignore = "requires CODEX_TEST_VOICE_RUNTIME containing real prepared native libraries"]
async fn relocated_runtime_initializes_closes_and_rejects_duplicate_initialization() -> Result<()> {
    let source = std::env::var_os("CODEX_TEST_VOICE_RUNTIME")
        .context("set CODEX_TEST_VOICE_RUNTIME to a matching prepared runtime")?;
    let source = fs::canonicalize(source)?;
    ensure!(
        source.join("runtime.json").is_file(),
        "prepared runtime receipt missing"
    );
    let directory = tempfile::Builder::new()
        .prefix("voice native package ")
        .tempdir()?;
    let root = directory.path().join("staging");
    let runtime = root.join("codex-resources/voice");
    fs::create_dir_all(&runtime)?;
    let mut pending = vec![(source, runtime.clone())];
    while let Some((source, destination)) = pending.pop() {
        for entry in fs::read_dir(source)? {
            let entry = entry?;
            let target = destination.join(entry.file_name());
            let kind = entry.file_type()?;
            if kind.is_dir() {
                fs::create_dir(&target)?;
                pending.push((entry.path(), target));
            } else {
                ensure!(kind.is_file(), "runtime inputs must be physical files");
                fs::copy(entry.path(), target)?;
            }
        }
    }
    let helper_source = cargo_bin("codex-voice-host")?;
    let name = helper_source.file_name().context("helper filename")?;
    fs::create_dir_all(runtime.join("bin"))?;
    codex_utils_cargo_bin::copy_executable(&helper_source, &runtime.join("bin").join(name))?;
    fs::create_dir(root.join("bin"))?;
    let app_name = if cfg!(windows) { "codex.exe" } else { "codex" };
    fs::write(root.join("bin").join(app_name), [])?;
    fs::write(root.join("codex-package.json"), "{}")?;
    let moved = directory.path().join("relocated package");
    fs::rename(root, &moved)?;
    let package = InstallContext::from_exe(
        /*is_macos*/ cfg!(target_os = "macos"),
        Some(&moved.join("bin").join(app_name)),
        /*method_override*/ None,
    )
    .package_layout
    .context("package layout")?;
    let output = timeout(
        DEADLINE,
        Command::new(&helper_source)
            .arg("--build-commit")
            .kill_on_drop(true)
            .output(),
    )
    .await??;
    ensure!(output.status.success(), "helper build identity failed");
    let build_commit = String::from_utf8(output.stdout)?.trim().to_owned();
    VoiceHost::connect(&package, &build_commit)
        .await?
        .initialize_runtime()
        .await?
        .close()
        .await?;

    let host = VoiceHost::connect(&package, &build_commit)
        .await?
        .initialize_runtime()
        .await?;
    assert!(host.initialize_runtime().await.is_err());
    Ok(())
}

